// The encoder of std/base64.ts under an instruction count: `n` rounds that
// each encode 4 KiB of generated bytes with base64Encode, then again in
// pieces of 1 to 64 bytes with base64EncodedLength and base64EncodeInto into
// one buffer. It reaches the three-byte groups, the padded tail and the
// alphabet lookup whose index and overflow sites the std/ ratchet counts, so
// a fix to one of them shows here as a count that holds or falls. It prints
// a sum of the output's bytes.
import { base64Encode, base64EncodedLength, base64EncodeInto } from "nish/base64"

/** The bytes each round encodes. */
const SOURCE_BYTES: i32 = 4096

export const main = (): i32 => {
  const n: i32 = 1200 // bench:n
  const src: u8[] = new Array<u8>(SOURCE_BYTES)
  let x: u32 = toU32(20261125)
  for (let i: i32 = 0; i < src.length; i++) {
    x = x * toU32(1103515245) + toU32(12345)
    src[i] = toU8(x >>> 24)
  }
  const dst: u8[] = new Array<u8>(base64EncodedLength(SOURCE_BYTES) + 4 * SOURCE_BYTES)
  let sum: i64 = 0
  for (let round: i32 = 0; round < n; round++) {
    const whole: string = base64Encode(src)
    sum += toI64(whole.length) + toI64(whole.charCodeAt(round % whole.length))
    let p: i32 = 0
    let at: i32 = 0
    let piece: i32 = 1 + (round % 7)
    while (p < SOURCE_BYTES) {
      const len: i32 = piece < SOURCE_BYTES - p ? piece : SOURCE_BYTES - p
      at = base64EncodeInto(src, p, len, dst, at)
      p += len
      piece = piece === 64 ? 1 : piece + 1
    }
    for (let k: i32 = 0; k < at && k < dst.length; k += 61) {
      sum += toI64(dst[k])
    }
  }
  console.log(`${sum}`)
  return 0
}
